import React, { useCallback, useState } from 'react';
import { SpotterEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_MODEL_ID } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';

function UpgradePrompt() {
  const { setTier } = useTier();

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F5F4FA' }}>
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: '#130829', margin: 0 }}>JETT AI</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '4px 0 0' }}>
          AI-powered natural language search across your travel data
        </p>
      </div>
      <div style={{ padding: '3rem 2.5rem' }}>
        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 16,
            padding: '3.5rem 2.5rem',
            textAlign: 'center',
            maxWidth: 520,
            margin: '0 auto',
            border: '1px solid #E5E7EB',
          }}
        >
          <div
            style={{
              width: 72,
              height: 72,
              borderRadius: '50%',
              backgroundColor: '#7C3AED',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              margin: '0 auto 1.5rem',
            }}
          >
            <svg width="32" height="32" viewBox="0 0 18 18" fill="none">
              <circle cx="9" cy="9" r="7" stroke="#A78BFA" strokeWidth="1.5"/>
              <circle cx="9" cy="9" r="3" fill="#A78BFA"/>
            </svg>
          </div>
          <h2 style={{ fontSize: 22, fontWeight: 700, color: '#130829', margin: '0 0 8px' }}>
            Upgrade to Pro
          </h2>
          <p style={{ fontSize: 15, color: '#6B7280', lineHeight: 1.6, margin: '0 0 1.5rem' }}>
            JETT AI lets you ask questions in plain English and get instant answers from your travel data. This feature is available on the <strong style={{ color: '#130829' }}>Pro</strong> tier.
          </p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12, alignItems: 'center' }}>
            <button
              onClick={() => setTier('Pro')}
              style={{
                backgroundColor: '#7C3AED',
                color: '#fff',
                border: 'none',
                padding: '12px 32px',
                borderRadius: 8,
                fontSize: 15,
                fontWeight: 600,
                cursor: 'pointer',
              }}
            >
              Upgrade to Pro
            </button>
            <span style={{ fontSize: 12, color: '#9CA3AF' }}>
              Includes AI Search, AI Highlights, and SpotIQ Analysis
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function Spotter() {
  const [embedError, setEmbedError] = useState<string | null>(null);
  const { spotterEnabled } = useTier();

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    const msg =
      err?.data?.errorMessage ||
      err?.message ||
      (typeof err === 'object' ? JSON.stringify(err) : String(err));
    setEmbedError(msg);
    console.error('[ThoughtSpot Spotter]', err);
  }, []);

  if (!spotterEnabled) {
    return <UpgradePrompt />;
  }

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#F5F4FA' }}>
      <div style={{ padding: '2rem 2.5rem 0' }}>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: '#130829', margin: 0 }}>JETT AI</h1>
        <p style={{ fontSize: 14, color: '#6B7280', margin: '4px 0 0' }}>
          Use natural language to search across your travel spend, flight data, and more
        </p>
      </div>

      <div style={{ padding: '1.5rem 2.5rem 2rem' }}>
        {embedError && (
          <div
            role="alert"
            style={{
              marginBottom: '1rem',
              padding: '0.75rem 1rem',
              background: '#FEF2F2',
              border: '1px solid #FECACA',
              borderRadius: 8,
              fontSize: 14,
              color: '#991B1B',
            }}
          >
            <strong>Embed error:</strong> {embedError}
          </div>
        )}

        <div
          style={{
            backgroundColor: '#fff',
            borderRadius: 12,
            overflow: 'hidden',
            minHeight: 'calc(100vh - 180px)',
          }}
        >
          <SpotterEmbed
            worksheetId={THOUGHTSPOT_MODEL_ID}
            onError={onError}
            hideSampleQuestions={true}
            style={{ width: '100%', height: 'calc(100vh - 180px)' }}
            customizations={{
              iconSpriteUrl: 'https://cdn.jsdelivr.net/gh/CamTS256/icon-store/robot11.svg',
            }}
          />
        </div>
      </div>
    </div>
  );
}
